%
% Hard-coded constants representing signal IDs and routings: ASID, SSID, SDID,
% and routings generated by code.
%
%
% IMPLEMENTATION NOTE: ASIDs, SSIDs, SDIDs are implemented as uint8 values for
% performance reasons. The implementation uses values per channel and CDF
% record which is too many instances for implementing them as objects, though
% that would have made the code simpler and more natural. This class supplies
% functions which correspond to the methods of such classes. The classes ASID,
% SSID, SDID (bicas.proc.L1L2.AntennaSignalId, bicas.proc.L1L2.SignalSourceId,
% bicas.proc.L1L2.SignalDestinationId) are only for defining metadata
% associated with each uint8 value and to make the implementation of above
% mentioned method-replacing functions easier.
%
%
% SUMMARY OF VALUES
% =================
% Copy-pasted. The code is the authoritative source. Not below text.
% --------------
% ASID:
% "DC_V1"  ⟼ 1
% "DC_V2"  ⟼ 2
% "DC_V3"  ⟼ 3
% "DC_V12" ⟼ 4
% "DC_V13" ⟼ 5
% "DC_V23" ⟼ 6
% "AC_V12" ⟼ 7
% "AC_V13" ⟼ 8
% "AC_V23" ⟼ 9
% --------------
% SSID:
% "DC_V1"   ⟼ 101
% "DC_V2"   ⟼ 102
% "DC_V3"   ⟼ 103
% "DC_V12"  ⟼ 104
% "DC_V13"  ⟼ 105
% "DC_V23"  ⟼ 106
% "AC_V12"  ⟼ 107
% "AC_V13"  ⟼ 108
% "AC_V23"  ⟼ 109
% "REF25V"  ⟼ 110
% "GND"     ⟼ 111
% "UNKNOWN" ⟼ 112
% -----------------
% SDID:
% "DC_V1"   ⟼ 201
% "DC_V2"   ⟼ 202
% "DC_V3"   ⟼ 203
% "DC_V12"  ⟼ 204
% "DC_V13"  ⟼ 205
% "DC_V23"  ⟼ 206
% "AC_V12"  ⟼ 207
% "AC_V13"  ⟼ 208
% "AC_V23"  ⟼ 209
% "NOWHERE" ⟼ 213
%
%
% Author: Erik P G Johansson, IRF, Uppsala, Sweden
%
classdef const
% NOTE: Feels like there should be a better way of implementing ASID, SSID,
%       SDIDs as uint8 + functions, but not sure how.
%
% PROPOSAL: Code for printing human-readable tables with values which can be
%           copy-pasted to comments in this file.

% PROPOSAL: Rename class to something implying the theme of ASID, SSID, SDID
%           rather than constants.
%   PRO: Contains function relating to ASID, SSID, SDID.
%   ~signal, ~channel
%   ~address, ~label, ~source/destination
%   ~id
%   sid = Signal ID(s)
%     PRO: Same components as in ASID, SSID, SDID.
%     CON: Abbreviation occurs in many words.
%   cid = Channel ID(s)
%
% PROPOSAL: Vectorize ASID/SSID/SDID functions.
%   PRO: Useful for vectorizing bicas.proc.L1L2.sat.
%   PRO: Can possibly abolish ASID, SSID, SDID classes if does so.
%
% PROPOSAL: Abolish ASID, SSID, SDID classes.
%   NOTE: ASID, SSID, SDID classes are only instantiated in this file, and are
%         most likely only used in this file too.
%
% PROPOSAL: Keep ASID, SSID, SDID as uint8 but also keep corresponding objects,
%           but defer functions on uint8 to object methods via dictionaries
%           uint8-->object. -- IMPLEMENTED
%   Ex: C.SSID_OBJ_DICT(ssid).is_ASR()
%   PRO: More natural way of hardcoding information about each uint8 value.
%   CON: Awkward to have two versions of ASID,SSID,SDID at the same time.
%     PRO: Separate names/abbreviations. 3-->2x3
%     CON: Use same abbreviations for both uint8 and objects.
%   CON: Still long calls.
%
% PROPOSAL: Hardcode information in structs (or objects) in private
%           dictionaries which bicas.proc.L1L2.const function implementations then use.
%   PRO: Automatic checks on uint8 (type), integer range (dictionary keys).
%   PRO: Does not need rely on adding/subtracting to translate between
%        ASID, SSID, SDID.
%
% PROPOSAL: Separate class constants for ASID, SSID, SDID respectively.
%   Replace .C --> .ASID (asid?), .SSID (ssid?) etc.
%   CON: Bad if wanting to "import" all constants at once.
%
% PROPOSAL: Rename ASID, SSID, SDID classes.
%   PRO: Clearer distinction between ASID/SSID/SDID classes and uint8 values.
%   CON: Different abbreviations?
%   ~definition
%   ~info, ~data, metadata
%   ~BLTS
%   --
%   SignalSourceDefinition
%   SignalSourceIdDefinition
%   SignalSourceIdInfo



  %###########
  %###########
  % CONSTANTS
  %###########
  %###########
  properties(Constant)



    C = bicas.proc.L1L2.const.init_const();



  end    % properties(Constant)



  %#######################
  %#######################
  % PUBLIC STATIC METHODS
  %#######################
  %#######################
  methods(Static, Access=public)



    % Define all constants for ASID, SSID, SDID, and Routing.
    %
    % IMPLEMENTATION NOTE: Defining one constant struct, which contains
    % multiple constants as fields. Makes it possible to access constants
    % through a variable copy of this constant rather than using the long
    % qualifiers.
    %
    % NOTE: Construction is problematic since bicas.proc.L1L2.Routing
    % constructors can not use other fields in bicas.proc.L1L2.const.C for
    % assertions, since it has not been initialized at that time. Also, bad
    % syntax in this code tends to give strange unintuitive error messages and
    % error behaviour in MATLAB.
    %
    % NOTE:
    function C2 = init_const()
      C2 = struct();

      C2.ASID_DICT     = configureDictionary('string', 'uint8');
      C2.ASID_OBJ_DICT = configureDictionary('uint8',  'bicas.proc.L1L2.AntennaSignalId');

      C2.SSID_DICT     = configureDictionary('string', 'uint8');
      C2.SSID_OBJ_DICT = configureDictionary('uint8',  'bicas.proc.L1L2.SignalSourceId');

      C2.SDID_DICT     = configureDictionary('string', 'uint8');
      C2.SDID_OBJ_DICT = configureDictionary('uint8',  'bicas.proc.L1L2.SignalDestinationId');

      C2.ROUTING_DICT  = configureDictionary('string', 'bicas.proc.L1L2.Routing');

      % Array of all ASR SDIDs.
      C2.SDID_ASR_AR   = uint8([]);

      % Global list of uint8 values used so far for defining ASIDs, SSIDs, and
      % SDIDs. This is used for avoiding collisions between all of the uint8
      % constants combined, not just within each category (for safety).
      allocatedUint8Ar = [];

      function allocate_new_uint8(k)
        assert(isnumeric(k))
        assert(~ismember(k, allocatedUint8Ar))
        allocatedUint8Ar(end+1) = k;
      end

      % (1) Add new SSID, SDID and ASID for the same ASR.
      % (2) Add Routing from ASR SSID to corresponding ASR SDID.
      function add_ASR_SSID_SDID_ASID_Routing(s, k, asidCategory, asidAntennas)
        asid = uint8(k);
        allocate_new_uint8(k)

        ssid = add_SSID(s, k, asid);
        sdid = add_SDID(s, k, asid);
        C2.SDID_ASR_AR(end+1, 1) = sdid;

        % Add ASID.
        AsidObj                = bicas.proc.L1L2.AntennaSignalId(ssid, asidCategory, asidAntennas);
        C2.ASID_DICT(s)        = asid;
        C2.ASID_OBJ_DICT(asid) = AsidObj;

        % Add Routing.
        C2.ROUTING_DICT(s)     = bicas.proc.L1L2.Routing(ssid, sdid);
      end

      % Add new SSID, only.
      function ssid = add_SSID(s, k, asidOrSpecialCase)
        ssid = uint8(k+100);
        allocate_new_uint8(ssid)

        SsidObj = bicas.proc.L1L2.SignalSourceId(asidOrSpecialCase);
        C2.SSID_DICT(s)        = ssid;
        C2.SSID_OBJ_DICT(ssid) = SsidObj;
      end

      % Add new SDID, only.
      function sdid = add_SDID(s, k, asidOrNowhere)
        sdid = uint8(k+200);
        allocate_new_uint8(sdid)

        SdidObj = bicas.proc.L1L2.SignalDestinationId(asidOrNowhere);
        C2.SDID_DICT(s)        = sdid;
        C2.SDID_OBJ_DICT(sdid) = SdidObj;
      end

      function main()
        % Ensure that certain "magic" numbers are not used for ASID, SSID, or
        % SDID.
        allocate_new_uint8(0)
        allocate_new_uint8(255)

        % ===========================================
        % Add ASID, SSID, SDID for every possible ASR
        % ===========================================
        add_ASR_SSID_SDID_ASID_Routing("DC_V1",  1, "DC_SINGLE", [1   ]);
        add_ASR_SSID_SDID_ASID_Routing("DC_V2",  2, "DC_SINGLE", [2   ]);
        add_ASR_SSID_SDID_ASID_Routing("DC_V3",  3, "DC_SINGLE", [3   ]);

        add_ASR_SSID_SDID_ASID_Routing("DC_V12", 4, "DC_DIFF",   [1, 2]);
        add_ASR_SSID_SDID_ASID_Routing("DC_V13", 5, "DC_DIFF",   [1, 3]);
        add_ASR_SSID_SDID_ASID_Routing("DC_V23", 6, "DC_DIFF",   [2, 3]);

        add_ASR_SSID_SDID_ASID_Routing("AC_V12", 7, "AC_DIFF",   [1, 2]);
        add_ASR_SSID_SDID_ASID_Routing("AC_V13", 8, "AC_DIFF",   [1, 3]);
        add_ASR_SSID_SDID_ASID_Routing("AC_V23", 9, "AC_DIFF",   [2, 3]);

        % =======================
        % Add all remaining SSIDs
        % =======================
        add_SSID("REF25V",  10, "REF25V");
        add_SSID("GND",     11, "GND");
        add_SSID("UNKNOWN", 12, "UNKNOWN");

        % =======================
        % Add all remaining SDIDs
        % =======================
        add_SDID("NOWHERE", 13, "NOWHERE");

        % ===================================================
        % Add all routings which are not ASR SSID to ASR SDID
        % ===================================================
        C2.ROUTING_DICT("REF25V_TO_DC_V1")    = bicas.proc.L1L2.Routing(C2.SSID_DICT("REF25V"),  C2.SDID_DICT("DC_V1"));
        C2.ROUTING_DICT("REF25V_TO_DC_V2")    = bicas.proc.L1L2.Routing(C2.SSID_DICT("REF25V"),  C2.SDID_DICT("DC_V2"));
        C2.ROUTING_DICT("REF25V_TO_DC_V3")    = bicas.proc.L1L2.Routing(C2.SSID_DICT("REF25V"),  C2.SDID_DICT("DC_V3"));
        C2.ROUTING_DICT("GND_TO_DC_V1")       = bicas.proc.L1L2.Routing(C2.SSID_DICT("GND"),     C2.SDID_DICT("DC_V1"));
        C2.ROUTING_DICT("GND_TO_DC_V2")       = bicas.proc.L1L2.Routing(C2.SSID_DICT("GND"),     C2.SDID_DICT("DC_V2"));
        C2.ROUTING_DICT("GND_TO_DC_V3")       = bicas.proc.L1L2.Routing(C2.SSID_DICT("GND"),     C2.SDID_DICT("DC_V3"));
        C2.ROUTING_DICT("UNKNOWN_TO_NOWHERE") = bicas.proc.L1L2.Routing(C2.SSID_DICT("UNKNOWN"), C2.SDID_DICT("NOWHERE"));
      end

      main()
    end



    %======
    % ASID
    %======

    % Can handle array argument, but return value is scalar.
    function bIsAsidAr = is_ASID(asidAr)
      assert(isa(asidAr, "uint8"))
      bIsAsidAr = all(ismember(asidAr, bicas.proc.L1L2.const.C.ASID_DICT.values), "ALL");
    end

    function asidCategory = get_ASID_category(asid)
      assert(isscalar(asid))
      asidCategory = bicas.proc.L1L2.const.C.ASID_OBJ_DICT(asid).category;
    end

    function antennas = get_ASID_antennas(asid)
      assert(isscalar(asid))
      antennas = bicas.proc.L1L2.const.C.ASID_OBJ_DICT(asid).antennas;
    end

    % Not vectorized.
    function ssid = ASID_to_SSID(asid)
      assert(isscalar(asid))
      ssid = bicas.proc.L1L2.const.C.ASID_OBJ_DICT(asid).ssid;
    end



    %======
    % SSID
    %======

    % Can handle array argument, but return value is scalar.
    function isSsid = is_SSID(ssidAr)
      assert(isa(ssidAr, "uint8"))

      isSsid = all(ismember(ssidAr, bicas.proc.L1L2.const.C.SSID_DICT.values), "ALL");
    end

    % Vectorized.
    function bIsAsrAr = SSID_is_ASR(ssidAr)
      assert(bicas.proc.L1L2.const.is_SSID(ssidAr))

      bIsAsrAr = ismember(ssidAr, bicas.proc.L1L2.const.C.SSID_DICT(...
        ["DC_V1", "DC_V2", "DC_V3", ...
        "DC_V12", "DC_V13", "DC_V23", ...
        "AC_V12", "AC_V13", "AC_V23"]));
    end

    % Not vectorized.
    % NOTE: Error if not ASR.
    function asid = SSID_ASR_to_ASID(ssid)
      assert(bicas.proc.L1L2.const.is_SSID(ssid) & isscalar(ssid))
      assert(bicas.proc.L1L2.const.SSID_is_ASR(ssid))

      asid = bicas.proc.L1L2.const.C.SSID_OBJ_DICT(ssid).asid;
      assert(bicas.proc.L1L2.const.is_ASID(asid))
    end

    % Vectorized.
    function bIsAcAr = SSID_is_AC(ssidAr)
      assert(bicas.proc.L1L2.const.is_SSID(ssidAr))

      bIsAcAr = ismember(ssidAr, bicas.proc.L1L2.const.C.SSID_DICT(...
        ["AC_V12", "AC_V13", "AC_V23"]));
    end

    % Vectorized
    function bIsDiffAr = SSID_is_diff(ssidAr)
      assert(bicas.proc.L1L2.const.is_SSID(ssidAr))

      bIsDiffAr = ismember(ssidAr, bicas.proc.L1L2.const.C.SSID_DICT(...
        ["DC_V12", "DC_V13", "DC_V23", ...
        "AC_V12", "AC_V13", "AC_V23"]));

      % CONCEPTUAL IMPLEMENTATION THAT DEFERS TO (NONEXISTENT) ASID FUNCTION.
      % bIsAsrAr            = SSID_is_ASR(ssidAr);
      % bIsDiffAr           = false(size(ssidAr));
      %
      % bIsDiffAr(bIsAsrAr) = ASID_is_diff(SSID_to_ASID(ssidAr(bIsAsrAr)));
    end



    %======
    % SDID
    %======

    function isSsid = is_SDID(sdidAr)
      assert(isa(sdidAr, "uint8"))
      isSsid = all(ismember(sdidAr, bicas.proc.L1L2.const.C.SDID_DICT.values), "ALL");
    end

    function isAsr = SDID_is_ASR(sdid)
      assert(isscalar(sdid))
      isAsr = bicas.proc.L1L2.const.C.SDID_OBJ_DICT(sdid).is_ASR();
    end

    % NOTE: Error if not ASR.
    function asid = SDID_ASR_to_ASID(sdid)
      assert(isscalar(sdid))
      assert(bicas.proc.L1L2.const.SDID_is_ASR(sdid))

      asid = bicas.proc.L1L2.const.C.SDID_OBJ_DICT(sdid).asid;
    end

    function isNowhere = SDID_is_nowhere(sdid)
      assert(bicas.proc.L1L2.const.is_SDID(sdid) & isscalar(sdid))
      isNowhere = (sdid == bicas.proc.L1L2.const.C.SDID_DICT("NOWHERE"));
    end



  end    % methods(Static, Access=public)



end
